var t=`1319-torta-frita`;var a=`world-1319`;var r=`UY`;var n=`south-america`;var o=8;var s=42;var u={en:`Torta Frita`,ua:`Торта фріта`};var l={en:`Torta Frita is a dish from Uruguay featuring all-purpose flour. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Торта фріта, страва кухні країни Уругвай з такими основними складниками: пшеничне борошно універсальне. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 14 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 14 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:14,i:[[`all-purpose-flour`,450,`g`],[`lard`,90,`g`],[`water`,220,`ml`],[`table-salt`,7,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 13 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 13 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:13,i:[[`canola-oil`,780,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-granulated-sugar`,105,`g`]]}];var g={slug:t,id:a,country:`UY`,region:n,servings:8,minutes:42,title:u,text:l,steps:d};export{r as country,g as default,a as id,s as minutes,n as region,o as servings,t as slug,d as steps,l as text,u as title};